   "source": {
    "quote": "예금의 이자는 최종거래일로부터 5년이 경과한 날부터는 이자를 원금에 더하지 않고, 계좌해지 또는 추가 입출금 거래 발생일의 다음 결산일에 일괄 계산하여 지급할 수 있습니다."
   },
   "let": {
    "dormant_period": {
     "date_range": {
      "from": {
       "anchor": "account.last_transaction_date",
       "offset_years": 5
      },
      "to": {
       "anchor": "contract.reference_date"
      }
     }
    }
   },
   "condition": {
    ">=": [
     {
      "count_distinct_months": {
       "event": "WITHDRAWAL",
       "within": {
        "ref": "$dormant_period"
       }
      }
     },
     60
    ]
   },
   "effect": {
    "type": "DORMANT_CONTRIBUTION"
   }
  }
 ]
}
